import { DayPlan, Drill, Phase } from "../learning-plan"
import { mcq, fill, fix, transform, write, speak } from "../drill-factory"

function mk(w:number,d:number,title:string,focus:string,theory:string,phases:Phase[]):DayPlan{
  return{week:w,day:d,title,focus,theory,phases}
}
function gp(prefix:string,fn:(pid:string,pn:number)=>Phase):Phase[]{
  return Array.from({length:10},(_,i)=>fn(`${prefix}p${i+1}`,i+1))
}

/* ── Week 4 · Day 1 ── Daily Standups & Team Updates ────────────────────── */

const W4D1=mk(4,1,
  "Daily Standups & Team Updates",
  "Speak clearly and confidently in daily standups — concise, specific, and professionally structured.",
  "Standup itu seperti check-in singkat tim setiap pagi — cukup 30 detik per orang. Tujuannya supaya semua orang tahu siapa sedang mengerjakan apa dan apakah ada yang perlu dibantu.\n\n**Formula standup** (30 detik per orang):\n1. **Kemarin**: 'I completed [nama task] and [apa yang dicapai].' (spesifik, bukan 'I did stuff')\n2. **Hari ini**: 'I am working on [task] and plan to [tonggak spesifik].' (ada target yang jelas)\n3. **Hambatan**: 'I am blocked on [X] because [Y]. I need [Z] from [orang] by [waktu].' (4 elemen: apa, mengapa, butuh apa, dari siapa, kapan)\n\n**Kesalahan berbicara yang umum**:\n- Terlalu panjang: menjelaskan BAGAIMANA caranya, bukan APA yang dikerjakan dan APA SELANJUTNYA.\n- Terlalu samar: 'I worked on things yesterday.' (tidak berguna sama sekali)\n- Hambatan tanpa detail: 'I have some issues.' (tidak bisa ditindaklanjuti)\n\n**Frasa standup IT yang penting**:\n- 'I picked up / wrapped up / handed off [task]' (mulai/selesai/serahkan task)\n- 'I am mid-way through / about 70% done with' (progres dengan persentase)\n- 'Waiting on [orang/tim] for [hal spesifik]' (menunggu sesuatu)\n- 'This is now blocked pending [tindakan]' (terhambat, perlu sesuatu)\n- 'I am flagging this as a risk to the sprint goal' (peringatan dini risiko sprint)",
  gp("w4d1",(pid,pn)=>{
    const TITLES=["Standup Language MCQ","Identify Good vs. Bad Standup","Blocker Description Quality","Speaking Fluency — Fill","IT Standup Vocabulary","Write Yesterday Section","Write Today Section","Write Full Standup","Speak 30-Second Standup","Speak Full Team Update"]
    const OBJS=["Identify correct standup structure and language.","Evaluate standup quality against professional standards.","Assess blocker descriptions for specificity and actionability.","Complete standup sentences with appropriate language.","Use precise IT vocabulary in spoken standup context.","Write a clear 'Yesterday' standup entry.","Write a clear 'Today' standup entry with specific goal.","Write a complete 3-part standup update.","Speak a 30-second standup aloud, clearly and confidently.","Speak a full 2-minute team update aloud."]
    const m=[
      mcq(`${pid}_01`,"Which 'Yesterday' item is best?",["a:I worked on the backend.","b:I was quite busy.","c:I completed the REST endpoint for user profile update (ENG-301) and merged the PR.","d:I did some code stuff."],"c","Item 'Yesterday' harus spesifik: task APA yang SELESAI, nomor tiketnya berapa, dan statusnya. 'I worked on the backend' tidak memberi informasi apa pun — tim tidak tahu apakah selesai, masih berjalan, atau terhambat."),
      mcq(`${pid}_02`,"Which 'Today' commitment is clearest?",["a:I'll try to work on the frontend.","b:I will start implementing the notification service (ENG-310) and aim to complete the data model by EOD.","c:I'll continue from yesterday.","d:Same as always."],"b","Item 'Today' harus punya KOMITMEN yang jelas: task spesifik apa, nomor tiketnya, dan tonggak (milestone) konkret yang ingin dicapai. 'I'll try to work on the frontend' bukan komitmen — itu hanya niat samar yang tidak bisa diandalkan tim."),
      mcq(`${pid}_03`,"'I'm blocked' — what must follow this?",["a:Nothing — the team will understand","b:What is blocked, why, what is needed, from whom, and by when","c:A list of all your tasks","d:An apology"],"b","Setiap blocker harus menjawab 5 pertanyaan: APA yang terhambat? MENGAPA terhambat? APA yang dibutuhkan? Dari SIAPA? KAPAN dibutuhkan? Tanpa informasi ini, tim tidak tahu harus membantu seperti apa."),
      mcq(`${pid}_04`,"'I'm about 50% through the refactor' is a good standup statement because:",["a:It is short","b:It gives a quantified sense of progress without over-explaining","c:It gives no useful information","d:It is always accurate"],"b","Perkiraan persentase ('50% done') adalah cara ringkas dan efektif untuk mengkomunikasikan progres tanpa harus menjelaskan detail teknisnya. Semua orang langsung mengerti seberapa jauh pekerjaanmu dan bisa menilai apakah sprint masih on track."),
      mcq(`${pid}_05`,"In a standup, saying 'Waiting on design for the new mockups' should also include:",["a:Nothing more","b:Who specifically, and by when you need the designs to stay on track","c:A complaint about the design team","d:The full design specification"],"b","Ketika 'menunggu' sesuatu dari orang lain, sertakan: DARI SIAPA kamu menunggu, KAPAN kamu membutuhkannya, dan APA DAMPAKNYA ke sprint kalau tidak datang tepat waktu. Tanpa detail ini, tidak ada yang tahu harus bertindak."),
      mcq(`${pid}_06`,"'I'm flagging this as a risk to the sprint goal' means:",["a:The sprint is cancelled","b:You are proactively warning the team that the sprint commitment may not be met","c:You are asking to remove the ticket","d:You want more time"],"b","Memasukkan 'sprint risk' artinya kamu SECARA PROAKTIF memperingatkan tim bahwa komitmen sprint mungkin tidak terpenuhi. Ini sangat dihargai — jauh lebih baik memberi tahu di awal daripada mengejutkan semua orang di hari terakhir sprint."),
      mcq(`${pid}_07`,"Which phrase transitions best from Yesterday to Today in a standup?",["a:'Anyway…'","b:'Moving on to today,'","c:'So… yeah,'","d:'Also,'"],"b","Transisi yang jelas membuat standupmu mudah diikuti. 'Moving on to today,' adalah cara profesional dan natural untuk berpindah dari 'Yesterday' ke 'Today'. Hindari 'Anyway...' atau 'So... yeah' yang terdengar kurang percaya diri dan tidak profesional."),
      mcq(`${pid}_08`,"A standup that exceeds 2 minutes per person is problematic because:",["a:It is rude","b:It wastes collective team time and often contains detail better handled one-to-one","c:Standups should be exactly 30 seconds","d:No one listens after 1 minute"],"b","Standup adalah untuk SINKRONISASI tim — bukan untuk problem-solving. Kalau seseorang berbicara lebih dari 2 menit, hampir pasti ada detail teknis yang tidak perlu dibahas di sini. Detail itu bisa dibahas secara terpisah setelah standup selesai."),
      mcq(`${pid}_09`,"'I wrapped up the payment integration' means:",["a:I am starting the payment integration","b:I completed and finished the payment integration","c:I need help with the payment integration","d:I reviewed the payment integration"],"b","'Wrapped up' artinya 'selesai dan tuntas'. Ini lebih kuat dari 'finished' biasa karena menyiratkan semua hal sudah bersih dan rampung. Contoh penggunaan lain: 'wrapped up the sprint review', 'wrapped up the discussion'."),
      mcq(`${pid}_10`,"When should you 'take something offline' after a standup?",["a:Never — resolve everything in the standup","b:When a discussion requires detailed problem-solving involving only some team members","c:For every topic","d:Only for technical topics"],"b","'Take offline' artinya diskusi lebih dalam dilakukan di luar standup — hanya dengan orang yang relevan. Standup bukan tempat problem-solving karena akan membuang waktu anggota tim lain yang tidak terlibat dalam masalah itu."),
      mcq(`${pid}_11`,"'Picking up a ticket' in standup means:",["a:Collecting a physical ticket","b:Starting to work on a task that was previously unassigned or in the backlog","c:Closing a completed ticket","d:Escalating an issue"],"b","'Picking up a ticket' artinya MULAI mengerjakan tugas yang sebelumnya belum diambil siapa pun — biasanya dari backlog. Kebalikannya: 'handing off a ticket' = menyerahkan ke orang lain."),
      mcq(`${pid}_12`,"Which blocker is most actionable?",["a:Things are complicated on my side.","b:I'm stuck on the OAuth integration.","c:I'm blocked on the OAuth token refresh — I need Sam to share the client secret for staging by 10:00 AM today; otherwise I can't complete ENG-287 this sprint.","d:The API is not working."],"c","Blocker yang bisa ditindaklanjuti menyebutkan: APA yang terhambat, SIAPA yang bisa membantu, KAPAN dibutuhkan, dan APA DAMPAKNYA ke sprint. Pilihan C menjawab semua pertanyaan itu — pilihan A, B, dan D tidak memberi informasi yang bisa ditindaklanjuti."),
      mcq(`${pid}_13`,"In a standup, you should avoid:",["a:Mentioning blockers","b:Giving specific ticket numbers","c:Explaining your implementation approach in detail — that belongs in a separate technical discussion","d:Quantifying your progress"],"c","Standup hanya menyebutkan APA yang dikerjakan, bukan BAGAIMANA caranya. Detail teknis seperti arsitektur atau implementasi dibahas di tempat lain — design review atau technical discussion. Kalau menjelaskan 'how', standup akan jauh melebihi batas waktu."),
      mcq(`${pid}_14`,"'I have no updates today' in a standup means:",["a:You did not work yesterday","b:Your status is unchanged — nothing new to report, no blockers","c:You skipped the standup","d:You are behind on your work"],"b","'No updates' itu valid! Artinya statusmu tidak berubah dari hari sebelumnya dan tidak ada hambatan baru. Yang penting, ini benar-benar berarti 'tidak ada perubahan', bukan 'tidak ada pekerjaan yang dilakukan'."),
      mcq(`${pid}_15`,"Which is the best way to report a completed sprint commitment?",["a:Done.","b:I delivered the checkout API (ENG-311) — tested in staging and merged. Ready for QA sign-off.","c:It is finished.","d:Check Jira."],"b","Melaporkan penyelesaian task yang baik mencakup: TASK apa yang selesai, VERIFIKASI statusnya (sudah ditest? sudah di-merge?), dan LANGKAH BERIKUTNYA (siap untuk QA sign-off). 'Done' sendirian tidak memberi informasi yang berguna bagi siapapun."),
      mcq(`${pid}_16`,"When you estimate 'EOD' (end of day) for a task, you should:",["a:Always deliver exactly at 5 PM","b:Intend to complete it during the working day and proactively communicate if this changes","c:Use it as a placeholder without commitment","d:Always add a day buffer"],"b","Kalau kamu berkomitmen 'EOD' tapi ada risiko tidak tercapai, BERITAHU TIM SESEGERA MUNGKIN — jangan tunggu jam 5 sore. Komunikasi proaktif jauh lebih profesional daripada memberi kejutan buruk di akhir hari kerja."),
      mcq(`${pid}_17`,"'Handing off' a task means:",["a:Dropping the task from the sprint","b:Transferring ownership of the task to another team member","c:Escalating the task to management","d:Closing the task without completing it"],"b","'Handing off' artinya MENYERAHKAN tanggung jawab atas suatu task ke orang lain sepenuhnya. Berbeda dari sekadar meminta bantuan — handing off berarti orang itu yang mengambil alih. Penting disebutkan di standup agar tidak ada task yang 'jatuh di tengah'."),
      mcq(`${pid}_18`,"A standup update should be prepared:",["a:During the standup itself","b:The night before or first thing in the morning — it should be ready and concise","c:By your manager","d:Only if you have blockers"],"b","Standup yang baik dipersiapkan SEBELUM rapat — malam sebelumnya atau pagi-pagi sebelum standup dimulai. Kalau baru memikirkannya saat standup berlangsung, kamu akan membuang waktu tim untuk menunggu dan hasilnya cenderung tidak spesifik."),
      mcq(`${pid}_19`,"'Mid-sprint check-in' vs 'daily standup' — what is different?",["a:Nothing — they are the same","b:Mid-sprint check-in typically covers sprint goal progress and forecast; standup covers daily tasks","c:Mid-sprint is longer","d:Mid-sprint is for managers only"],"b","Mid-sprint check-in membahas gambaran BESAR: apakah sprint goal masih bisa tercapai? Standup harian membahas hal SPESIFIK: apa yang dikerjakan hari ini dan hambatannya. Keduanya penting tapi untuk tujuan yang berbeda."),
      mcq(`${pid}_20`,"Which phrase correctly flags a risk without alarming the team unnecessarily?",["a:'We're going to miss the deadline — this sprint is a disaster.'","b:'I want to flag that ENG-320 is running about a day behind. I'm working through it but wanted the team to be aware.'","c:'Don't worry, everything is fine.'","d:'I have no comment on the timeline.'"],"b","Melaporkan risiko harus FAKTUAL (berdasarkan data: 'terlambat 1 hari'), TIDAK MENGKHAWATIRKAN BERLEBIHAN (bukan 'sprint disaster'), dan TRANSPARAN. Tujuannya memberi informasi agar tim bisa mengambil keputusan — bukan menimbulkan kepanikan."),
      mcq(`${pid}_21`,"After a standup, action items should be:",["a:Forgotten — standups are just for communication","b:Written down immediately with owners and deadlines","c:Discussed again in the next standup","d:Emailed to everyone"],"b","Action items dari standup harus dicatat SEGERA setelah standup selesai — sebelum semua orang kembali ke pekerjaan masing-masing. Setiap action item harus jelas: SIAPA yang bertanggung jawab dan KAPAN harus selesai."),
      mcq(`${pid}_22`,"'I'm on track' in a standup is:",["a:Always sufficient","b:Useful only if the team knows your target — otherwise add: 'on track to deliver ENG-301 by Thursday'","c:Too vague to be useful","d:Overconfident"],"b","'On track' tanpa konteks kurang berguna. Tim perlu tahu: on track untuk APA? Kapan? Selalu sertakan referensi konkret: 'on track to deliver ENG-301 by Thursday' — jauh lebih informatif dari sekadar 'I'm on track'."),
      mcq(`${pid}_23`,"In a remote standup, you should:",["a:Always use video on","b:Have your camera on where possible, minimise background noise, and speak directly to the team","c:Text-only is always preferred","d:Join late if needed"],"b","Di standup remote, kamera menyala (kalau memungkinkan) membantu membangun koneksi tim. Minimalisasi noise latar belakang dan bicara langsung ke kamera — bukan ke layar chat. Ini menunjukkan rasa hormat dan profesionalisme kepada rekan tim."),
      mcq(`${pid}_24`,"The standup is NOT the place to:",["a:Mention blockers","b:Give a progress update","c:Problem-solve and debug collaboratively with one team member while others wait","d:Flag sprint risks"],"c","Standup BUKAN tempat untuk problem-solving atau debugging bersama — itu membuang waktu anggota tim yang tidak terlibat. Kalau ada masalah yang perlu didiskusikan, selesaikan standup dulu, lalu ajak orang yang relevan untuk diskusi terpisah setelahnya."),
      mcq(`${pid}_25`,"Which phrase is best for introducing a new development in a standup?",["a:'Oh yeah, I forgot to mention —'","b:'I also want to raise that the requirements for ENG-305 changed this morning — this may affect the sprint timeline.'","c:'Something came up.'","d:'FYI there's a thing.'"],"b","Kalau ada perkembangan baru, sampaikan dengan spesifik: task apa yang terpengaruh (ENG-305), apa yang berubah (requirements), dan APA DAMPAKNYA ke sprint. Jangan hanya bilang 'something came up' — tim tidak tahu harus bereaksi seperti apa."),
    ]
    const drills:Drill[]=[]
    for(let i=0;i<25;i++){
      const id=`${pid}_${String(i+1).padStart(2,"0")}`
      if(pn<=4) drills.push(m[i%m.length])
      else if(pn===5) drills.push(fix(id,`Yesterday I did some work and it went okay.\nToday I'll work on more stuff.\nBlockers: there are some issues with the environment.`,`Yesterday: I completed the payment gateway error handling (ENG-287) and pushed to staging.\nToday: I will start the webhook integration (ENG-290) and target completion of the event schema by EOD.\nBlockers: The staging webhook endpoint is not responding. I need ops to check the reverse proxy config — blocking ENG-290. Flagging as sprint risk.`,"Standup: specific tasks, tickets, and actionable blocker."))
      else if(pn<=7) drills.push(fill(id,`I am ___ the authentication refactor. It is approximately ___ % complete and I am on ___ to finish by Thursday. No ___ at this time.`,["wrapping up","75","track","blockers"],"Standup phrases: wrapping up, percentage, on track, no blockers."))
      else if(pn===8) drills.push(write(id,`Write a complete standup update (Yesterday / Today / Blockers) for this scenario:\nYesterday you finished designing the database schema for the notification system and created the Jira subtasks. Today you will start building the backend service. You need the frontend team to share their API contract by noon today — otherwise you cannot align the response format.`,80))
      else if(pn===9) drills.push(speak(id,"Speak your standup in exactly 30–45 seconds:\nYesterday: You reviewed 3 PRs and merged 2. Today: You will implement the user permissions model. Blockers: You are waiting for the security team to approve the permissions spec — you need it by end of today."))
      else drills.push(speak(id,"Speak a 2-minute team update as if presenting to the whole engineering team:\nCover your progress this week, one challenge you solved, what you are delivering tomorrow, and any risks to the sprint goal."))
    }
    return{id:pid,phaseNumber:pn,title:TITLES[pn-1],objective:OBJS[pn-1],drills}
  })
)

/* ── Week 4 · Day 2 ── Presenting Technical Ideas ───────────────────────── */

const W4D2=mk(4,2,
  "Presenting Technical Ideas & Proposals",
  "Structure and deliver clear technical proposals — architecture decisions, feature pitches, and design reviews.",
  "Proposal teknis yang baik itu tidak sekadar bilang 'kita harus ganti sistemnya'. Kamu harus menjelaskan MENGAPA, BAGAIMANA, dan APA risikonya — supaya orang lain bisa membuat keputusan yang tepat.\n\n**Struktur proposal teknis**:\n1. **Masalah**: Apa masalah yang ada sekarang? (1-2 kalimat yang jelas)\n2. **Solusi yang diusulkan**: Apa rekomendasimu? (jelas dan spesifik)\n3. **Cara kerjanya**: Gambaran teknis singkat — gunakan satu analogi kalau audiensnya campuran teknis dan non-teknis\n4. **Trade-off**: Apa kelebihannya? Apa kekurangan atau risikonya?\n5. **Rekomendasi**: Ajakan bertindak yang jelas dengan timeline\n\n**Bahasa untuk mengusulkan**:\n- 'I'd like to propose…' (saya ingin mengusulkan)\n- 'My recommendation is to…' (rekomendasi saya adalah)\n- 'The advantage of this approach is…' (kelebihan pendekatan ini adalah)\n- 'One trade-off to consider is…' (satu hal yang perlu dipertimbangkan adalah)\n- 'I believe this is the right direction because…' (saya percaya ini arah yang tepat karena)\n\n**Hedging yang tepat (jangan terlalu lemah atau terlalu kuat)**:\n- Terlalu lemah: 'Maybe we could possibly consider…' (tidak meyakinkan)\n- Terlalu kuat: 'We must do this immediately.' (terkesan memaksa)\n- Pas: 'I strongly recommend… because… The main risk is… which we can mitigate by…'",
  gp("w4d2",(pid,pn)=>{
    const TITLES=["Proposal Language MCQ","Structure Identification","Trade-off Communication","Recommendation Strength","Handling Q&A","Fill — Proposal Opening","Fill — Trade-off Section","Write a Problem Statement","Write a Full Proposal","Speak: Architecture Decision"]
    const OBJS=["Choose appropriate language for technical proposals.","Identify correct proposal structure in a technical presentation.","Communicate trade-offs clearly and balanced.","Calibrate recommendation language — not too weak or too strong.","Respond to technical questions professionally.","Complete a proposal opening with appropriate language.","Complete a trade-off analysis section.","Write a clear, specific problem statement for a technical proposal.","Write a complete 5-part technical proposal.","Speak: deliver an architecture decision recommendation aloud."]
    const m=[
      mcq(`${pid}_01`,"Which is the most professional way to open a technical proposal?",["a:'I think maybe we should…'","b:'My recommendation is to migrate to a microservices architecture because the current monolith is causing deployment bottlenecks.'","c:'We need to do this immediately.'","d:'I have an idea, but you might not like it.'"],"b","Pembuka proposal yang baik langsung menyatakan REKOMENDASI dan ALASANNYA. Jangan mulai dengan ragu-ragu ('I think maybe...') — itu langsung membuat pendengar kurang percaya. Bersikaplah percaya diri tapi tetap terbuka untuk diskusi."),
      mcq(`${pid}_02`,"'One trade-off to consider is that this approach increases complexity' — this is:",["a:Too negative","b:Professional — balancing the proposal with an honest risk assessment","c:Too vague","d:Unnecessary in a proposal"],"b","Proposal yang jujur mengakui trade-off — kelebihan DAN kekurangannya. Ini justru meningkatkan kredibilitasmu: kamu menunjukkan sudah berpikir matang, bukan hanya menjual ide secara satu sisi. Orang lebih percaya rekomendasimu kalau kamu jujur soal risikonya."),
      mcq(`${pid}_03`,"When presenting a technical option you do NOT recommend, you should:",["a:Skip it entirely","b:Present it fairly, then explain why you recommend the alternative","c:Dismiss it immediately","d:Recommend it instead"],"b","Presentasikan semua opsi secara ADIL, termasuk yang tidak kamu rekomendasikan. Ini menunjukkan kamu sudah melakukan analisis yang menyeluruh. Stakeholder juga bisa membuat keputusan yang lebih baik kalau mereka memahami seluruh landscape-nya, bukan hanya satu opsi."),
      mcq(`${pid}_04`,"'I strongly recommend adopting TypeScript across all our services' is:",["a:Too aggressive","b:Appropriate — clear, confident recommendation","c:Too vague","d:A question, not a recommendation"],"b","Rekomendasi yang kuat dan percaya diri itu tepat — selama didukung oleh bukti dan alasan yang jelas. Jangan terlalu melunak kalau kamu yakin dengan rekomendasimu. Keyakinan yang didukung data jauh lebih meyakinkan dari keraguan yang berlebihan."),
      mcq(`${pid}_05`,"When a stakeholder asks a question you cannot answer in a presentation, you should:",["a:Guess an answer confidently","b:Say 'I'll need to follow up on that — can I get back to you by [date]?'","c:Ignore the question and move on","d:Redirect to a team member without confirming"],"b","Kalau kamu tidak tahu jawabannya, lebih baik akui dan berkomitmen untuk follow up dengan tanggal spesifik. Menebak-nebak dan ternyata salah akan merusak kredibilitasmu jauh lebih parah dari mengakui ketidaktahuan dengan jujur."),
      mcq(`${pid}_06`,"'The advantage of this approach is' should be followed by:",["a:A vague claim like 'it's better'","b:A specific, measurable benefit: 'a 40% reduction in deployment time based on our proof of concept'","c:A list of all features","d:The implementation details"],"b","Klaim keunggulan harus SPESIFIK dan kalau bisa, TERUKUR. '40% reduction in deployment time based on our proof of concept' jauh lebih meyakinkan dari 'it's better'. Angka dan bukti konkret membuat rekomendasimu jauh lebih kuat dan dipercaya."),
      mcq(`${pid}_07`,"'The main risk is that this requires 3 months of refactoring' — this statement is:",["a:Too discouraging","b:Honest and specific — good risk communication","c:Vague","d:Should not be included in a proposal"],"b","Menyebutkan risiko secara SPESIFIK ('membutuhkan 3 bulan refactoring') membangun kepercayaan dan memungkinkan stakeholder membuat keputusan berdasarkan informasi lengkap. Menyembunyikan risiko hanya menunda masalah dan merusak kepercayaan saat masalah itu muncul."),
      mcq(`${pid}_08`,"When presenting to a mixed technical and non-technical audience, you should:",["a:Use only non-technical language","b:Use full technical detail for accuracy","c:Layer your explanation: start with the business impact, then briefly explain the technical approach","d:Present twice — once for each audience"],"c","Untuk audiens campuran, gunakan pendekatan berlapis: mulai dengan DAMPAK KE BISNIS yang semua orang pahami, baru kemudian penjelasan teknis singkat untuk yang ingin tahu lebih dalam. Ini memastikan semua orang bisa mengikuti tanpa ada yang merasa kebingungan."),
      mcq(`${pid}_09`,"'This is the only right approach' in a technical proposal is problematic because:",["a:It is too short","b:It closes down discussion and may undermine trust if stakeholders have concerns","c:It is too formal","d:Nothing is wrong with it"],"b","Bahasa absolut ('this is the ONLY right approach') menutup ruang untuk diskusi dan bisa merusak kepercayaan kalau ada celah dalam argumenmu. Selalu sisakan ruang untuk masukan: 'I strongly recommend this — though I'm open to discussing alternatives.'"),
      mcq(`${pid}_10`,"A good 'call to action' at the end of a proposal should:",["a:End with 'Any questions?'","b:Request a specific decision or next step with a timeline: 'I'd like approval to begin the proof of concept by next Wednesday.'","c:Summarise everything you said","d:Defer to the audience"],"b","'Call to action' yang baik meminta keputusan atau langkah SPESIFIK dengan batas waktu yang jelas. Jangan hanya bertanya 'Any questions?' — tanyakan 'I'd like approval to begin the proof of concept by next Wednesday.' Spesifisitas mendorong tindakan nyata."),
      mcq(`${pid}_11`,"'We could potentially explore the possibility of…' is problematic because:",["a:It is too short","b:It is excessively hedged — it signals lack of confidence in your recommendation","c:It is too formal","d:It is grammatically incorrect"],"b","Terlalu banyak hedging ('could potentially explore the possibility of') membuat rekomendasimu terdengar tidak meyakinkan. Bersikaplah langsung dan percaya diri: 'I recommend X.' Kamu bisa tetap terbuka terhadap masukan tanpa harus melunak berlebihan."),
      mcq(`${pid}_12`,"When comparing two technical solutions, the best structure is:",["a:Solution A is good. Solution B is bad.","b:Here are the criteria we evaluated against. Solution A scores well on performance but has higher operational cost. Solution B is cheaper but requires more engineering effort. I recommend Solution A because performance is our primary constraint.","c:List all features of both","d:Pick one and ignore the other"],"b","Perbandingan dua solusi yang baik mengikuti struktur: KRITERIA penilaian → EVALUASI masing-masing solusi → REKOMENDASI dengan alasan jelas. Ini membuat keputusan terasa objektif berdasarkan standar yang disepakati, bukan preferensi pribadi."),
      mcq(`${pid}_13`,"'Based on our analysis…' is a good proposal phrase because:",["a:It sounds technical","b:It signals that the recommendation is evidence-based, not arbitrary","c:It is formal","d:It is shorter than alternatives"],"b","'Based on our analysis' menunjukkan rekomendasimu bukan tebakan — ada data dan analisis di baliknya. Ini meningkatkan kepercayaan audiens. Selalu tautkan rekomendasimu ke bukti konkret, bukan hanya intuisi atau preferensi."),
      mcq(`${pid}_14`,"When presenting an ADR (Architecture Decision Record), you should include:",["a:Only the chosen solution","b:Context, decision, alternatives considered, and consequences","c:The full implementation code","d:A comparison table only"],"b","ADR (Architecture Decision Record) mencatat keputusan arsitektur penting. Harus mencakup: konteks masalah, keputusan yang diambil, alternatif yang dipertimbangkan, dan konsekuensinya. Ini penting agar tim di masa depan mengerti MENGAPA keputusan itu dibuat — bukan hanya APA yang diputuskan."),
      mcq(`${pid}_15`,"'I'm open to feedback on this' at the end of a proposal signals:",["a:You are unsure of your recommendation","b:You are confident but collaborative — you value the team's input","c:You need approval","d:The proposal is not finished"],"b","'I'm open to feedback' bukan tanda ketidakpastian — justru sebaliknya. Ini menunjukkan kamu cukup percaya diri untuk mengundang kritik, dan cukup kolaboratif untuk menghargai masukan orang lain. Proposal yang melibatkan tim lebih mungkin mendapat dukungan."),
      mcq(`${pid}_16`,"Which opening is best for a design review?",["a:'I spent two weeks on this so please be nice.'","b:'I'll walk you through the proposed architecture and I am specifically looking for feedback on the data model and the security approach.'","c:'Here's what I built.'","d:'This is probably not perfect but...'"],"b","Buka design review dengan dua hal: APA yang akan dibahas dan JENIS FEEDBACK apa yang kamu butuhkan. Ini membantu reviewer fokus pada hal yang paling penting dan menghasilkan feedback yang lebih berkualitas dan berguna."),
      mcq(`${pid}_17`,"'We have three options. I'll present them all and then share my recommendation.' — this approach is:",["a:Too time-consuming","b:Effective — it shows rigour and lets stakeholders understand the full landscape","c:Confusing","d:Only appropriate for senior audiences"],"b","Menyajikan semua opsi lalu memberikan rekomendasi menunjukkan kamu sudah berpikir menyeluruh (rigorous). Stakeholder bisa membuat keputusan yang lebih baik karena mereka memahami seluruh landscape-nya — bukan hanya menerima satu opsi yang disodorkan."),
      mcq(`${pid}_18`,"When a stakeholder challenges your proposal, you should first:",["a:Defend your position immediately","b:Acknowledge their concern, clarify if needed, then respond with evidence","c:Dismiss the concern","d:Withdraw the proposal"],"b","Ketika ada yang menantang proposalmu, jangan langsung membela diri. Langkah yang tepat: AKUI kekhawatirannya dulu, KLARIFIKASI kalau perlu, baru RESPONS dengan bukti. Ini menunjukkan kamu benar-benar mendengarkan — bukan hanya menunggu giliran bicara."),
      mcq(`${pid}_19`,"'This will definitely solve all our scaling problems' is a problematic claim because:",["a:It is too short","b:Overclaiming damages credibility — prefer 'This should significantly improve our scaling capacity based on the load tests.'","c:It is too technical","d:Nothing is wrong"],"b","Terlalu klaim ('will DEFINITELY solve all problems') merusak kredibilitas — tidak ada yang pasti di dunia engineering. Gunakan pernyataan yang dikualifikasi: 'should significantly improve based on load tests'. Ini lebih jujur dan justru lebih dipercaya."),
      mcq(`${pid}_20`,"The best way to handle a question that derails your presentation is:",["a:Stop the presentation and answer it fully","b:'That's a great point — let's come back to it at the end so I can keep the flow. I'll make a note.'","c:Ignore it","d:Ask the person to leave"],"b","Pertanyaan yang keluar dari topik bisa mengganggu alur presentasimu. Cara profesional: 'That's a great point — let me note it and come back to it at the end.' Ini menghormati pertanyaan tanpa membiarkan presentasimu kehilangan fokus dan molor."),
      mcq(`${pid}_21`,"Visual aids in a technical presentation should:",["a:Contain all the detail in text form","b:Show what is hard to explain in words — diagrams, flow charts, key metrics — not walls of text","c:Be avoided entirely","d:Be used for every sentence"],"b","Visual aid yang baik menampilkan sesuatu yang SULIT dijelaskan dengan kata-kata — diagram aliran data, arsitektur sistem, grafik performa. Bukan hanya menyalin teks ke dalam slide. 'Wall of text' di slide justru membuat audiens kehilangan fokus."),
      mcq(`${pid}_22`,"'Let me demonstrate with a quick example' is effective because:",["a:It wastes time","b:Concrete examples make abstract technical concepts immediately understandable","c:It shows you prepared","d:It fills time"],"b","Contoh konkret membuat konsep abstrak langsung bisa dipahami. Setiap kali menjelaskan konsep teknis, siapkan minimal satu contoh yang relevan. 'Let me show you with a quick example' adalah kalimat paling kuat yang bisa kamu ucapkan dalam presentasi teknis."),
      mcq(`${pid}_23`,"When proposing a major refactor, you must address:",["a:Only the technical benefits","b:Business impact, timeline, team effort required, and risk mitigation plan","c:Only the timeline","d:Only what is broken now"],"b","Proposal refactor besar harus menjawab empat pertanyaan: Apa DAMPAKNYA ke bisnis? Berapa LAMA? Berapa BESAR effort timnya? Apa RISIKONYA dan bagaimana mitigasinya? Tanpa keempat elemen ini, sulit bagi stakeholder untuk membuat keputusan yang tepat."),
      mcq(`${pid}_24`,"'The team disagrees with my proposal' — the professional response is:",["a:Ignore the disagreement and proceed","b:Understand their concerns, evaluate them honestly, and either refine the proposal or explain why you still recommend it","c:Escalate to management immediately","d:Withdraw the proposal"],"b","Ketika tim tidak setuju, langkah yang tepat: PAHAMI kekhawatiran mereka, EVALUASI dengan jujur apakah ada poinnya, lalu PERBARUI proposalmu atau JELASKAN mengapa kamu tetap merekomendasikannya. Jangan abaikan atau langsung eskalasi."),
      mcq(`${pid}_25`,"A proposal meeting ends without a decision. You should:",["a:Accept that no decision was made","b:Summarise the options, note the concerns raised, and propose a specific follow-up: 'I'll send a summary by tomorrow and request a decision by Thursday.'","c:Repeat the entire presentation","d:Send a complaint email"],"b","Kalau rapat berakhir tanpa keputusan, jangan biarkan begitu saja. Rangkum opsi yang ada, catat kekhawatiran yang diungkapkan, dan usulkan langkah konkret berikutnya dengan deadline yang jelas. Ini menjaga momentum dan menghindari rapat yang terasa sia-sia."),
    ]
    const drills:Drill[]=[]
    for(let i=0;i<25;i++){
      const id=`${pid}_${String(i+1).padStart(2,"0")}`
      if(pn<=4) drills.push(m[i%m.length])
      else if(pn===5) drills.push(fix(id,`I think maybe we could possibly look at switching to a different database, maybe PostgreSQL, but I'm not sure if that's the right thing to do because there are trade-offs.`,`I recommend migrating from MySQL to PostgreSQL. The primary driver is better support for JSONB columns, which will reduce our query complexity by approximately 30%. The main trade-off is a 2-week migration effort, which I propose we schedule for Q3.`,"Proposals: remove hedging, add specific benefits and timeline."))
      else if(pn<=7) drills.push(fill(id,`The ___ of adopting a caching layer is a projected 60% reduction in database load. The main ___ is that it introduces cache invalidation complexity, which we can ___ by implementing a write-through strategy.`,["advantage","trade-off","mitigate"],"Trade-off language: advantage, trade-off, mitigate."))
      else if(pn===8) drills.push(write(id,`Write a clear 2-sentence problem statement for this scenario:\nThe current monolithic application takes 45 minutes to build and deploy. This means hotfixes during incidents take too long to reach production, increasing mean time to recovery (MTTR).`,50))
      else if(pn===9) drills.push(write(id,`Write a complete 5-part technical proposal:\nProblem: API response times have increased 3× since last release.\nRecommendation: Add Redis caching for the most expensive endpoints.\nInclude: how it works, trade-offs, and a specific call to action.`,150))
      else drills.push(speak(id,"Speak for 90 seconds: present an architecture decision to your team. Choose one: (1) move from a monolith to microservices, or (2) adopt Kubernetes for deployment. Cover the problem, your recommendation, one trade-off, and your call to action."))
    }
    return{id:pid,phaseNumber:pn,title:TITLES[pn-1],objective:OBJS[pn-1],drills}
  })
)

/* ── Week 4 · Day 3 ── Handling Disagreement & Code Reviews ─────────────── */

const W4D3=mk(4,3,
  "Handling Disagreement & Code Review Communication",
  "Disagree professionally, give constructive code review feedback, and resolve conflict through clear language.",
  "Tidak setuju itu wajar di dunia teknis. Yang penting caranya profesional — fokus pada argumen dan data, bukan pada orangnya.\n\n**Tingkat bahasa untuk tidak setuju**:\n- Ringan: 'I see this slightly differently…' (saya melihatnya sedikit berbeda)\n- Sedang: 'I'd like to offer a different perspective on this.' (saya ingin berbagi sudut pandang yang berbeda)\n- Kuat: 'I have a significant concern about this approach. Could we discuss it before proceeding?' (ada kekhawatiran serius, minta diskusi dulu)\n\n**Nada feedback code review**:\n- Buruk: 'This is wrong.' (langsung menghakimi)\n- Buruk: 'Why would you do it this way?' (terkesan menyerang)\n- Baik: 'This approach works, though consider using X instead — it reduces the risk of Y.' (akui yang baik, lalu kasih saran spesifik)\n- Baik: 'Nit: [saran kecil] — feel free to ignore if you prefer it as is.' ('Nit' = komentar kecil yang tidak wajib diikuti)\n\n**Frasa untuk menolak dengan sopan**:\n- 'I understand the reasoning, but I want to raise a concern about…' (mengerti, tapi ada kekhawatiran)\n- 'That's a valid point — I'd still recommend we consider…' (poinnya valid, tapi tetap merekomendasikan)\n- 'Could we run a small experiment to validate this before committing?' (usul coba dulu sebelum komit)\n\n**Menyelesaikan jalan buntu**: 'Let's agree on the criteria first, then evaluate each option against them.' (sepakati kriteria dulu, baru nilai tiap opsi — jadi objektif, bukan subjektif)",
  gp("w4d3",(pid,pn)=>{
    const TITLES=["Disagreement Language MCQ","Code Review Tone MCQ","Giving Constructive Feedback","Receiving Feedback Language","Conflict Resolution Phrases","Fill — Code Review Comment","Fill — Disagreement Response","Write a Code Review Comment","Write a Disagreement Response","Speak: Technical Disagreement"]
    const OBJS=["Choose appropriate language for professional disagreement.","Evaluate code review comments for tone and constructiveness.","Formulate constructive, specific code review feedback.","Respond professionally to code review criticism.","Use conflict resolution language to reach consensus.","Complete a professional code review comment.","Complete a professional disagreement response.","Write a constructive, specific code review comment.","Write a professional response to a disagreement in a design discussion.","Speak: role-play a professional technical disagreement."]
    const m=[
      mcq(`${pid}_01`,"Which response to a colleague's proposal is most professional?",["a:'That's a terrible idea.'","b:'I see the reasoning, but I'm concerned about the latency implications. Could we benchmark it first?'","c:'Whatever you think is fine.'","d:'This will never work.'"],"b","Cara profesional untuk tidak setuju: AKUI dulu penalarannya ('I see the reasoning'), kemudian sampaikan KEKHAWATIRAN SPESIFIK ('concerned about latency'), dan USULKAN TINDAKAN ('Could we benchmark it first?'). Tiga langkah ini membuat ketidaksetujuanmu terdengar konstruktif, bukan konfrontatif."),
      mcq(`${pid}_02`,"Which code review comment is most constructive?",["a:'Wrong.'","b:'This function is too long.'","c:'This function has four responsibilities — consider splitting it into smaller, single-purpose functions to improve testability.'","d:'I don't like this.'"],"c","Komentar code review yang baik menjawab tiga hal: APA masalahnya (fungsi punya 4 tanggung jawab), MENGAPA itu masalah (mengurangi testability), dan SARAN SPESIFIK (pecah menjadi fungsi-fungsi lebih kecil). 'Wrong' tidak memberi informasi apa pun untuk diperbaiki."),
      mcq(`${pid}_03`,"'Nit:' in a code review comment means:",["a:A critical bug","b:A minor style or preference comment that is not a blocker","c:A required change","d:A security vulnerability"],"b","'Nit' (singkatan dari 'nitpick') adalah komentar kecil tentang gaya atau preferensi — bukan masalah kritis. Kalau reviewer tulis 'Nit:', artinya: 'saran kecil, tidak wajib diikuti, dan tidak akan menghalangi PR untuk di-merge'. Sangat berguna untuk membedakan mana komentar penting dan mana yang opsional."),
      mcq(`${pid}_04`,"When a reviewer marks your code as 'Request changes', you should:",["a:Ignore the feedback","b:Review the comments carefully, address each one with a response or fix, then re-request review","c:Close the PR and start over","d:Ask the reviewer to approve regardless"],"b","Ketika reviewer meminta perubahan, perlakukan setiap komentar secara individual: PERBAIKI atau JELASKAN mengapa tidak perlu diubah, lalu minta review ulang. Jangan abaikan komentar — bahkan kalau tidak setuju, respons secara eksplisit supaya reviewer tahu kamu sudah membacanya."),
      mcq(`${pid}_05`,"'Have you considered using a map here instead of a nested loop?' is:",["a:Too vague","b:A good code review question — invites the author to think, not just comply","c:Too demanding","d:Too casual for code review"],"b","Pertanyaan di code review lebih efektif daripada pernyataan — mereka mengundang penulis kode untuk berbagi penalarannya dulu. Mungkin ada alasan bagus mengapa kode ditulis seperti itu. Kalau langsung bilang 'ganti ke map()', kamu mungkin melewatkan konteks penting."),
      mcq(`${pid}_06`,"The phrase 'I'd like to offer a different perspective' is useful because:",["a:It is more formal","b:It signals disagreement while keeping the conversation open and non-confrontational","c:It is shorter","d:It avoids the topic"],"b","'I'd like to offer a different perspective' terdengar jauh lebih sopan dari 'kamu salah'. Ini membuka ruang untuk dialog — orang tidak merasa diserang sehingga lebih terbuka untuk mendengarkan pandanganmu. Pilihan kata yang tepat bisa membuat perbedaan besar dalam dinamika tim."),
      mcq(`${pid}_07`,"'This is technically correct but I think it could be more readable. Suggestion: [example]' is a good code review comment because:",["a:It is short","b:It acknowledges correctness, identifies the specific issue, and offers a concrete alternative","c:It avoids giving an opinion","d:It demands a change"],"b","Komentar code review terbaik: akui APA YANG BAIK dulu ('technically correct'), kemudian sebut MASALAH SPESIFIK ('could be more readable'), dan berikan SARAN KONKRET. Jauh lebih mudah diterima daripada langsung mengkritik tanpa mengakui pekerjaan yang sudah benar."),
      mcq(`${pid}_08`,"When you disagree with a senior engineer's technical decision, you should:",["a:Say nothing to avoid conflict","b:Raise your concern professionally with specific reasoning, then defer if they remain unconvinced after discussion","c:Immediately escalate to your manager","d:Override their decision"],"b","Kalau tidak setuju dengan keputusan senior engineer: SAMPAIKAN kekhawatiranmu dengan alasan spesifik, DISKUSIKAN terbuka, dan kalau mereka tetap tidak setuju setelah mendengar argumenmu — IKUTI keputusannya secara profesional. Ini bukan menyerah, ini menunjukkan kedewasaan profesional."),
      mcq(`${pid}_09`,"'Let's agree on the criteria first' is effective in a technical deadlock because:",["a:It wastes time","b:It shifts focus from opinions to shared standards, making the decision objective","c:It avoids the issue","d:It always leads to your preferred outcome"],"b","'Sepakati kriteria dulu' adalah teknik cerdas untuk menyelesaikan kebuntuan teknis. Ketika semua orang setuju dengan STANDAR yang digunakan untuk menilai, keputusan menjadi objektif — bukan soal siapa yang paling keras bicara atau paling senior. Contoh kriteria: performa, biaya, kompleksitas, maintainability."),
      mcq(`${pid}_10`,"'I hear what you're saying, and…' as a response to criticism is:",["a:Too casual","b:A good active listening signal before responding to a concern","c:Dismissive","d:Aggressive"],"b","'I hear what you're saying' menunjukkan kamu benar-benar MENDENGARKAN sebelum merespons — bukan hanya menunggu giliran bicara. Ini adalah sinyal active listening yang sangat penting. Orang lebih terbuka menerima responsmumu kalau mereka merasa didengar terlebih dahulu."),
      mcq(`${pid}_11`,"Which code review comment needs improvement?",["a:Consider using early return here to reduce nesting.","b:This could be more efficient.","c:This recursive call may cause a stack overflow for inputs > 10,000 items — consider an iterative approach.","d:Missing error handling for the null case — this will throw a NullPointerException in production."],"b","'Could be more efficient' terlalu samar untuk berguna. Siapa yang mengerjakan kode tidak tahu harus mengubah apa. Bandingkan dengan pilihan C: menyebut MASALAH SPESIFIK (stack overflow untuk input >10.000), penyebabnya, dan saran konkret (iterative approach). Spesifisitas adalah kunci."),
      mcq(`${pid}_12`,"'Blocking' vs 'non-blocking' code review comment means:",["a:About async code","b:Blocking = must be fixed before merge; non-blocking = suggestion or preference","c:About access permissions","d:Both mean the same thing"],"b","'Blocking' = HARUS diperbaiki sebelum PR di-merge. 'Non-blocking' = saran atau preferensi yang opsional. Membedakan keduanya sangat membantu penulis kode mengetahui mana yang prioritas dan mana yang bisa diabaikan tanpa risiko."),
      mcq(`${pid}_13`,"When your code review comment is marked 'Resolved' without being addressed, you should:",["a:Accept it and approve","b:Reopen the conversation: 'I don't think this has been fully addressed — could you clarify or implement the fix?'","c:Escalate to management immediately","d:Withdraw your comment"],"b","Kalau komentar reviewmu ditandai 'Resolved' tapi sebenarnya belum ditangani, kamu berhak untuk membuka kembali percakapan itu. Lakukan dengan sopan dan spesifik — jelaskan bagian mana yang menurutmu belum ditangani. Jangan abaikan karena takut konflik."),
      mcq(`${pid}_14`,"'I could be wrong, but…' before a code review comment is:",["a:A good humility signal","b:Unnecessary hedging that undermines your feedback — state the concern directly","c:Required for tone","d:Too casual"],"b","'I could be wrong, but...' sebelum komentar code review melemahkan feedbackmu. Kalau kamu melihat masalah, sampaikan dengan langsung. Kamu bisa tetap sopan tanpa terlalu melunak: 'Consider using X here — it reduces risk of Y' sudah cukup langsung dan konstruktif."),
      mcq(`${pid}_15`,"The best response to 'I disagree with your approach' in a design meeting is:",["a:'No, I'm right.'","b:'Can you help me understand your concern specifically? I'd like to make sure I'm considering all the implications.'","c:'Okay, we'll do it your way.'","d:'Let's ask management.'"],"b","Ketika seseorang bilang 'I disagree', langkah pertama yang tepat adalah MEMAHAMI kekhawatiran SPESIFIK mereka — bukan langsung membela posisimu. Mungkin mereka melihat sesuatu yang kamu lewatkan. 'Can you help me understand your concern?' membuka dialog yang produktif."),
      mcq(`${pid}_16`,"When you have a strong opinion in a technical debate, you should:",["a:Refuse to compromise","b:Make your case clearly with evidence, listen to counter-arguments, and be willing to update your position if the evidence warrants it","c:Let the most senior person decide","d:Vote immediately"],"b","Boleh punya pendapat teknis yang kuat — selama berbasis bukti dan kamu tetap terbuka untuk mengubah posisimu kalau ada bukti yang lebih kuat. Inilah yang membedakan engineer yang baik: bukan yang selalu benar, tapi yang selalu mau memperbarui pandangan berdasarkan bukti terbaik."),
      mcq(`${pid}_17`,"'Approve with comments' in a code review means:",["a:The PR is rejected","b:The code can merge but the reviewer has suggestions worth considering","c:All comments must be addressed first","d:The reviewer is unavailable"],"b","'Approve with comments' artinya kode SIAP untuk di-merge — reviewer menyetujuinya — tapi ada beberapa saran yang worth considering. Saran-saran itu tidak wajib diikuti sebelum merge. Berbeda dari 'Request changes' yang berarti ada hal yang HARUS diperbaiki dulu."),
      mcq(`${pid}_18`,"Which phrase best signals you are reconsidering your position?",["a:'Fine, you win.'","b:'Actually, that's a fair point — let me reconsider.'","c:'I'll do what you say.'","d:'I give up.'"],"b","'That's a fair point — let me reconsider' menunjukkan kamu mempertimbangkan argumen orang lain dengan serius — ini kolaborasi yang tulus, bukan menyerah terpaksa. Jauh lebih profesional dari 'Fine, you win' yang terkesan tidak ikhlas atau resentful."),
      mcq(`${pid}_19`,"In a code review, you find a potential security vulnerability. You should:",["a:Comment 'fix this' and move on","b:Mark it as blocking, describe the specific risk, and suggest the fix","c:Approve and mention it verbally","d:File a bug report instead of commenting in the PR"],"b","Kerentanan keamanan harus selalu 'blocking' — kode tidak boleh di-merge sebelum ini diperbaiki. Sertakan: DESKRIPSI RISIKO yang spesifik (apa yang bisa terjadi kalau dieksploitasi) dan SARAN PERBAIKAN yang konkret. 'Fix this' tidak cukup — jelaskan apa dan mengapa."),
      mcq(`${pid}_20`,"'This is just my opinion — feel free to disagree' is appropriate when:",["a:Making a critical decision","b:Sharing a personal style preference in code review where there is no objective right answer","c:Reporting a bug","d:Always"],"b","'This is just my opinion' hanya tepat untuk preferensi gaya yang genuinely opsional — di mana tidak ada jawaban benar atau salah yang objektif. Jangan gunakan untuk masalah kebenaran (correctness) atau keamanan — itu bukan opini, itu fakta teknis."),
      mcq(`${pid}_21`,"When giving negative feedback in a code review, you should:",["a:Also mention what is done well, to maintain a constructive relationship","b:Only mention what is wrong","c:Send the feedback privately, not in the PR","d:Avoid giving negative feedback entirely"],"a","Feedback yang seimbang lebih mudah diterima. Sebutkan apa yang SUDAH BAIK sebelum atau sesudah memberikan kritik. Ini bukan soal pujian palsu — tapi soal memberikan gambaran yang akurat dan membangun hubungan kerja yang baik untuk jangka panjang."),
      mcq(`${pid}_22`,"'I'd push back on this decision' means:",["a:You are removing the decision","b:You are professionally disagreeing with or questioning the decision","c:You are accepting the decision","d:You are escalating to management"],"b","'Push back' dalam konteks profesional artinya TIDAK SETUJU atau MEMPERTANYAKAN suatu keputusan secara profesional — bukan menolak atau menghapus keputusan itu. 'I want to push back on this' = 'Saya punya kekhawatiran yang ingin saya sampaikan.'"),
      mcq(`${pid}_23`,"When a teammate takes code review feedback personally, you should:",["a:Avoid giving them feedback in future","b:Clarify that your comments are about the code, not the person, and focus on technical reasoning","c:Escalate to the manager","d:Apologise and withdraw your feedback"],"b","Code review harus SELALU tentang kodenya, bukan tentang orangnya. Kalau rekanmu tersinggung, jelaskan dengan baik bahwa komentarmu adalah tentang kode — bukan tentang kemampuan atau karakter mereka. Fokus pada argumen teknis yang objektif."),
      mcq(`${pid}_24`,"'This is a great PR overall — one thing worth discussing before merging:' is effective because:",["a:It is long","b:It leads with genuine acknowledgement before raising a concern — keeps the tone constructive","c:It is formal","d:It avoids giving feedback"],"b","Memulai dengan pengakuan yang tulus ('great PR overall') membuat kritik yang menyusul jauh lebih mudah diterima. Ini komunikasi yang efektif — orang lebih siap mendengar masukan kritis kalau mereka tahu upaya mereka dihargai terlebih dahulu."),
      mcq(`${pid}_25`,"Which is the most useful 'Approved' comment?",["a:LGTM","b:Approved — nice clean solution. One optional suggestion in the comments, but feel free to merge as is.","c:Fine.","d:Good I guess."],"b","Bahkan komentar persetujuan yang baik menyebutkan SECARA SPESIFIK apa yang bagus dan memperjelas STATUS komentar yang ada — apakah harus diubah sebelum merge atau opsional. 'LGTM' sudah cukup, tapi 'Approved — nice clean solution. One optional suggestion, feel free to merge' jauh lebih informatif."),
    ]
    const drills:Drill[]=[]
    for(let i=0;i<25;i++){
      const id=`${pid}_${String(i+1).padStart(2,"0")}`
      if(pn<=4) drills.push(m[i%m.length])
      else if(pn===5) drills.push(fix(id,`This is wrong. Why would you use a for loop here? Obviously you should use map().`,`This works, though consider using \`map()\` here instead — it makes the intent clearer and avoids the manual index management. Happy to discuss if you had a reason for the loop.`,"Code review: replace criticism with specific suggestion + open to discussion."))
      else if(pn<=7) drills.push(fill(id,`I ___ your recommendation, though I'd like to ___ a concern about the memory implications. Could we ___ a load test before committing to this approach?`,["understand","raise","run"],"Disagreement: acknowledge → raise concern → propose action."))
      else if(pn===8) drills.push(write(id,`Write a constructive code review comment for this scenario:\nA colleague's PR uses a deeply nested if-else chain (5 levels) in a critical function. The code works but is hard to read and test. Suggest an improvement with specific reasoning.`,80))
      else if(pn===9) drills.push(write(id,`Write a professional response to this design review comment:\n'Your proposed database schema stores JSON blobs for user preferences. This will make it impossible to query preferences efficiently as the product scales.'\nYou agree with part of this but believe the alternative (normalised tables) has its own trade-offs for your use case.`,100))
      else drills.push(speak(id,"Speak for 90 seconds: role-play a situation where you disagree with a colleague's technical choice. Start by acknowledging their reasoning, then explain your concern with specific evidence, and propose a way to resolve the disagreement (e.g., a test, a benchmark, or agreeing on criteria)."))
    }
    return{id:pid,phaseNumber:pn,title:TITLES[pn-1],objective:OBJS[pn-1],drills}
  })
)

/* ── Week 4 · Day 4 ── Client & Stakeholder Communication ───────────────── */

const W4D4=mk(4,4,
  "Client & Stakeholder Communication",
  "Communicate technical information to clients and non-technical stakeholders clearly, professionally, and empathetically.",
  "Komunikasi dengan klien itu seperti menjelaskan sesuatu ke orang tuamu yang tidak paham teknologi — fokus pada DAMPAKNYA, bukan cara teknisnya bekerja.\n\n**Prinsip utama komunikasi dengan klien**:\n1. **Mulai dengan dampak**, bukan teknologi: 'Users cannot log in' (dampaknya), BUKAN langsung 'the OAuth token refresh is failing' (teknis).\n2. **Bahasa sederhana**: hindari jargon teknis kecuali kliennya memang orang teknis.\n3. **Komunikasi proaktif**: beritahu mereka sebelum mereka yang bertanya lebih dulu.\n4. **Empati dulu**: akui dulu dampaknya terhadap bisnis mereka, baru jelaskan.\n5. **Timeline konkret**: 'by 17:00 UTC today', BUKAN 'soon' (segera itu tidak bermakna).\n\n**Mengelola ekspektasi**:\n- 'I want to set realistic expectations: this will take approximately 3 business days.'\n- 'We are investigating — I will provide a full update by [waktu].'\n\n**Menyampaikan pesan sulit**:\n- Keterlambatan: akui → jelaskan dengan sederhana → berikan timeline baru → tindakan apa yang diambil.\n- Insiden: minta maaf → jelaskan dampak → jelaskan apa yang sudah dilakukan → langkah selanjutnya.\n- Perubahan scope: jelaskan mengapa → ukur perubahannya → usulkan pilihan-pilihan.\n\n**Saat menerima feedback demo**: 'Thank you for the feedback. Let me confirm I've captured this correctly: you'd like [X] changed to [Y]. Is that right?' (konfirmasi ulang supaya tidak ada salah paham)",
  gp("w4d4",(pid,pn)=>{
    const TITLES=["Client Communication MCQ","Plain Language Conversion","Managing Expectations","Delivering Bad News","Handling Scope Change","Fill — Incident Update to Client","Fill — Expectation Setting","Write a Client Incident Email","Write a Scope Change Explanation","Speak: Client Demo Debrief"]
    const OBJS=["Evaluate client communication for tone, clarity, and professionalism.","Convert technical language to plain English for a client.","Use appropriate language to manage client expectations.","Deliver bad news (delays, incidents) professionally and empathetically.","Explain scope changes clearly with options.","Complete a client-facing incident update template.","Complete an expectation-setting message template.","Write a professional client incident email.","Write a clear, professional scope change explanation with options.","Speak: debrief a client demo and capture feedback professionally."]
    const m=[
      mcq(`${pid}_01`,"Which message to a client best explains an ongoing incident?",["a:The API is down because of a null pointer exception in the auth service.","b:We are aware that some users are currently unable to log in. Our team is investigating and will provide a full update by 15:00 UTC.","c:We're looking into it.","d:There's a technical problem on our end."],"b","Update klien yang baik mencakup tiga hal: AKUI DAMPAKNYA (siapa yang terpengaruh), SEBUTKAN TINDAKAN yang diambil, dan BERIKAN ETA SPESIFIK. Jangan gunakan istilah teknis seperti 'null pointer exception' — klien tidak butuh tahu itu, mereka butuh tahu kapan masalahnya selesai."),
      mcq(`${pid}_02`,"'The database is experiencing high I/O contention' should be simplified to:",["a:The system has backend issues.","b:The database is overloaded — it is processing more requests than it can handle, which is causing slow response times.","c:The DB has a problem.","d:There are I/O issues."],"b","Istilah teknis seperti 'high I/O contention' tidak berguna untuk klien. Terjemahkan ke bahasa yang menggambarkan DAMPAKNYA: 'database overloaded — menerima lebih banyak permintaan dari yang bisa ditangani, sehingga respons menjadi lambat.' Fokus pada apa yang DIRASAKAN pengguna."),
      mcq(`${pid}_03`,"'We'll try to have it done soon' to a client should be replaced with:",["a:Nothing — soon is fine","b:'We are targeting [date] for completion. I will confirm once this is achieved.'","c:'It's almost done.'","d:'Please be patient.'"],"b","'Soon' tidak berarti apa-apa bagi klien — mereka tidak tahu apakah itu 10 menit atau 10 hari. Selalu ganti dengan tanggal dan waktu yang SPESIFIK: 'We are targeting 15 May by 17:00 UTC.' Spesifisitas mengurangi kecemasan dan menunjukkan profesionalisme."),
      mcq(`${pid}_04`,"An incident has been resolved. Your first message to the client should:",["a:Explain the technical root cause in detail","b:Confirm the service is restored, state the duration of the issue, and commit to a follow-up report","c:Apologise and nothing else","d:Wait for the client to contact you first"],"b","Ketika insiden selesai, pesan pertama ke klien harus mencakup: KONFIRMASI layanan sudah kembali normal, BERAPA LAMA masalah berlangsung, dan KOMITMEN untuk laporan follow-up (post-mortem). Jangan hanya bilang 'it's fixed' — berikan gambaran lengkap."),
      mcq(`${pid}_05`,"A client asks for a feature that was not in the original scope. The best response is:",["a:We can do that, no problem.","b:I'd like to assess the impact of this request. I'll come back to you with a timeline and any cost implications by [date]. Does that work?","c:That's out of scope.","d:You should have told us earlier."],"b","Kalau klien minta fitur baru di luar scope, JANGAN langsung bilang 'ya, bisa' atau 'tidak bisa'. Langkah yang tepat: NILAI dampaknya dulu (waktu, biaya, scope), kemudian RESPONS dengan informasi konkret dan batas waktu yang jelas untuk jawabannya."),
      mcq(`${pid}_06`,"'I want to set realistic expectations' is useful because:",["a:It sounds technical","b:It signals transparency and prepares the client for a timeline or limitation they may not want to hear","c:It avoids commitment","d:It is required in contracts"],"b","'I want to set realistic expectations' adalah cara profesional untuk mempersiapkan klien terhadap berita yang mungkin tidak mereka inginkan — sebelum mereka kecewa. Lebih baik jujur di awal daripada mengecewakan di akhir. Transparansi membangun kepercayaan jangka panjang."),
      mcq(`${pid}_07`,"Which phrase best acknowledges a client's frustration professionally?",["a:'That's not our fault.'","b:'I completely understand your frustration — this is clearly impacting your team. Here is what we are doing about it:'","c:'Calm down, it's being fixed.'","d:'This is a complicated technical issue.'"],"b","Ketika klien frustrasi, respon pertamamu harus EMPATI — akui dampaknya terhadap bisnis mereka. Baru kemudian jelaskan apa yang sedang dilakukan. Jangan langsung masuk ke solusi teknis tanpa mengakui dulu betapa mengganggunnya situasi ini bagi mereka."),
      mcq(`${pid}_08`,"When explaining a missed deadline to a client, you must include:",["a:An apology only","b:What happened, revised timeline, and what steps are being taken to prevent recurrence","c:A detailed technical explanation","d:Team member names who are responsible"],"b","Ketika deadline terlewat, klien perlu tiga hal: APA YANG TERJADI (penjelasan singkat yang mudah dipahami), TIMELINE BARU yang realistis, dan LANGKAH PENCEGAHAN agar tidak terulang. Hanya minta maaf saja tidak cukup — mereka perlu tahu ke depannya akan seperti apa."),
      mcq(`${pid}_09`,"'As per our SLA, we are not obligated to…' in a client message is:",["a:Appropriate and professional","b:Technically correct but likely to damage the client relationship — lead with what you are doing, not what you don't have to do","c:Required for legal clarity","d:A good way to open a difficult conversation"],"b","Meskipun secara teknis benar, 'as per our SLA...' terdengar defensif dan legalistik — dan langsung merusak hubungan dengan klien. Selalu mulai dengan APA YANG KAMU LAKUKAN untuk membantu, bukan apa yang tidak wajib kamu lakukan berdasarkan kontrak."),
      mcq(`${pid}_10`,"In a demo debrief, the best way to capture feedback is:",["a:Take notes silently","b:'Let me confirm I've captured this correctly: you'd like X changed to Y. Is that accurate?'","c:'Okay, I'll fix everything.'","d:'We'll see what we can do.'"],"b","Konfirmasi feedback secara EKSPLISIT — ulangi kembali apa yang kamu dengar dengan kata-katamu sendiri. Ini memastikan tidak ada salah paham antara apa yang klien maksud dan apa yang tim akan kerjakan. Satu konfirmasi singkat bisa menghemat berminggu-minggu pekerjaan yang sia-sia."),
      mcq(`${pid}_11`,"'The feature will be delayed by 3 days' — the best way to tell a client is:",["a:Email with no explanation","b:'I want to proactively let you know that the [feature] delivery will shift from [original date] to [new date]. This is due to [brief reason]. I will send a full update by [time].'","c:Send in the standup notes","d:Wait until the original deadline passes"],"b","Beritahukan penundaan SECARA PROAKTIF — sebelum klien yang bertanya. Sertakan: tanggal baru yang SPESIFIK, ALASAN SINGKAT yang mudah dipahami, dan KOMITMEN untuk update selanjutnya. Proaktivitas menunjukkan profesionalisme dan mengurangi kekhawatiran klien."),
      mcq(`${pid}_12`,"When a client says 'We need this by tomorrow' and it's not feasible, you should:",["a:Say yes and miss the deadline","b:'I want to be honest with you — delivering the full feature by tomorrow is not feasible. What I can deliver by then is [partial deliverable]. Shall we discuss what works best?'","c:'That's impossible.'","d:Say nothing until tomorrow"],"b","Kalau klien minta sesuatu yang tidak feasible dalam waktu yang mereka inginkan, bersikaplah JUJUR dengan jelas — tapi tawarkan ALTERNATIF: apa yang BISA dikirimkan dalam waktu tersebut? Kemudian buka DISKUSI tentang apa yang paling berguna bagi mereka."),
      mcq(`${pid}_13`,"'We are currently investigating the root cause' should be followed by:",["a:Nothing — wait until resolved","b:An ETA for the next update, even if not a resolution ETA: 'I will send another update in 30 minutes.'","c:The full technical explanation","d:A list of potential causes"],"b","Saat masih investigasi dan belum ada solusi, tetap berikan ETA untuk UPDATE BERIKUTNYA — meski bukan ETA untuk solusinya. 'I will send another update in 30 minutes' memberi klien kepastian bahwa mereka tidak diabaikan, meski masalahnya belum terselesaikan."),
      mcq(`${pid}_14`,"A post-mortem report shared with a client should:",["a:Include all internal technical details","b:Be a summary: impact, duration, what was done, root cause in plain language, and prevention actions","c:Blame the third-party vendor","d:Focus only on the resolution"],"b","Post-mortem untuk klien harus dalam bahasa sederhana dan fokus pada: DAMPAK (siapa yang terpengaruh), DURASI (berapa lama), TINDAKAN (apa yang dilakukan), PENYEBAB dalam bahasa sederhana, dan PENCEGAHAN ke depannya. Detail teknis internal tidak perlu dimasukkan."),
      mcq(`${pid}_15`,"'I'll escalate this internally' means:",["a:You are refusing the request","b:You are raising the issue to senior members of your team who have authority to make decisions or allocate resources","c:You are delaying the response","d:The client needs to wait indefinitely"],"b","'I'll escalate this internally' artinya membawa isu ini ke tingkat yang lebih tinggi dalam tim — orang-orang yang punya wewenang untuk membuat keputusan atau mengalokasikan sumber daya. Untuk klien, ini berarti isu mereka ditangani dengan serius di level yang tepat."),
      mcq(`${pid}_16`,"When a client requests a feature that conflicts with your technical architecture, you should:",["a:Reject it immediately","b:Explain the constraint in plain terms, quantify the effort, and offer alternatives","c:Build it without mentioning the complexity","d:Ignore the request"],"b","Ketika ada kendala teknis yang membatasi permintaan klien, jelaskan dalam bahasa sederhana, estimasikan usaha yang dibutuhkan, dan tawarkan ALTERNATIF. Klien lebih mudah menerima keterbatasan kalau disertai opsi lain yang bisa memenuhi kebutuhan mereka."),
      mcq(`${pid}_17`,"'We take full responsibility for this incident' to a client signals:",["a:Legal liability","b:Accountability and professionalism — clients value transparency over blame-shifting","c:Weakness","d:That your team made a mistake that shouldn't be admitted"],"b","'We take full responsibility' bukan tanda kelemahan — justru sebaliknya. Ini menunjukkan AKUNTABILITAS dan profesionalisme yang tinggi. Klien menghargai transparansi. Mencoba mengalihkan kesalahan atau membuat excuses jauh lebih merusak kepercayaan dari mengakui kesalahan secara langsung."),
      mcq(`${pid}_18`,"Which is the most professional way to decline a client request?",["a:'No.'","b:'We are unable to accommodate this request at this time. The earliest we could begin this work is [date], once [condition] is met. Would that timeline work for you?'","c:'That's not possible.'","d:'We'll try but no promises.'"],"b","Menolak permintaan klien secara profesional berarti: jelaskan MENGAPA tidak bisa sekarang, sebutkan KAPAN PALING AWAL bisa dilakukan, dan tanyakan apakah itu acceptable bagi mereka. Ini menunjukkan kamu menghargai permintaan mereka sambil tetap jujur tentang keterbatasan."),
      mcq(`${pid}_19`,"After a production incident, you should contact the client:",["a:Only after a full root cause analysis is complete","b:As soon as you are aware of client impact — with a brief initial message and a promise of updates","c:Only if the client contacts you first","d:Once the incident is fully resolved"],"b","Kontak pertama ke klien harus dilakukan SESEGERA MUNGKIN setelah kamu tahu ada dampak ke mereka — bahkan sebelum kamu punya jawaban atau solusi. Pesan singkat 'We are aware of an issue and investigating now' sudah cukup. Diam jauh lebih merusak dari pesan yang belum lengkap."),
      mcq(`${pid}_20`,"'I will send you a follow-up by end of day' to a client means:",["a:You might send something","b:A firm commitment — you must send the update by end of business even if there is no resolution","c:Tomorrow is fine too","d:The issue will be resolved by end of day"],"b","Kalau kamu berjanji 'I will send an update by end of day', itu KOMITMEN yang harus dipenuhi — bahkan kalau belum ada resolusi. Kirimkan update dengan informasi yang ada. Jangan biarkan deadline komitmenmu terlewat tanpa kabar — itu menghancurkan kepercayaan."),
      mcq(`${pid}_21`,"Which is the best response to a client who is unhappy with the product demo?",["a:'It's just a prototype.'","b:'Thank you for this feedback — it's very helpful. Let me confirm the specific changes you'd like: [list]. I'll discuss these with the team and come back to you with a timeline by [date].'","c:'We can't change this now.'","d:'Did you read the brief?'"],"b","Ketika klien memberi feedback negatif tentang demo: BERTERIMA KASIH atas feedbacknya (genuine — feedback itu berharga), KONFIRMASI secara spesifik apa yang mereka minta (ulangi dengan kata-katamu), dan KOMITMEN dengan timeline yang jelas untuk merespons."),
      mcq(`${pid}_22`,"'We are working around the clock on this' is:",["a:Unprofessional","b:Acceptable in a client incident update — it signals urgency and resource commitment","c:Overpromising","d:Always false"],"b","'Working around the clock' (bekerja siang dan malam) menunjukkan tim sangat serius menangani masalah ini dengan semua sumber daya yang ada. Ini tepat untuk insiden kritis yang sangat mempengaruhi klien — menunjukkan urgensi dan komitmen yang mereka ingin dengar."),
      mcq(`${pid}_23`,"A client emails asking for an update on a pending feature. The best response time is:",["a:Within the week","b:Within the same business day — even if you have no new information, acknowledge receipt and give an update ETA","c:Only when you have a full answer","d:When your manager approves"],"b","Setiap pertanyaan klien harus diakui DALAM HARI YANG SAMA — bahkan kalau kamu belum punya jawabannya. 'I received your message and will get back to you by [waktu]' sudah cukup. Membiarkan pertanyaan klien tidak terjawab lebih dari satu hari kerja mengirim sinyal buruk."),
      mcq(`${pid}_24`,"'This change will require an additional 5 days of development' — what must you also provide?",["a:Nothing — the timeline is enough","b:A brief explanation of why, the impact on the delivery date, and whether this affects cost or scope","c:A technical diagram","d:Team member names"],"b","Ketika menyampaikan perubahan timeline, sertakan: MENGAPA berubah (alasan singkat), DAMPAKNYA ke tanggal delivery (tanggal baru spesifik), dan apakah ini mempengaruhi BIAYA atau SCOPE. Tanpa informasi ini, klien tidak bisa membuat keputusan bisnis yang tepat."),
      mcq(`${pid}_25`,"The best closing for a client incident update is:",["a:'Talk soon.'","b:'I will send a detailed post-mortem report within 24 hours. Please do not hesitate to contact me if you have any questions in the meantime.'","c:'Hopefully this won't happen again.'","d:'Sorry.'"],"b","Penutup pesan insiden yang baik menyebutkan LANGKAH KONKRET BERIKUTNYA (post-mortem report dalam 24 jam) dan menyatakan KETERSEDIAANMU untuk pertanyaan kapan pun. Ini memberi klien kepastian bahwa insiden ini akan ditindaklanjuti secara menyeluruh."),
    ]
    const drills:Drill[]=[]
    for(let i=0;i<25;i++){
      const id=`${pid}_${String(i+1).padStart(2,"0")}`
      if(pn<=4) drills.push(m[i%m.length])
      else if(pn===5) drills.push(fix(id,`Hi, we had a null pointer exception in the JWT middleware which caused the OAuth token validation to fail and the auth service threw 401s. It's being fixed.`,`Dear [Client],\n\nWe are aware that some users are currently unable to log in to [product]. Our team identified the issue and a fix is being deployed now. We expect full service restoration by 15:30 UTC.\n\nI will send a follow-up confirmation once service is fully restored.\n\nApologies for the disruption.\n\n[Your name]`,"Client incident: no jargon, impact, action, specific ETA."))
      else if(pn<=7) drills.push(fill(id,`I want to ___ let you know that the delivery of the reporting module will shift from 15 May to 18 May. This is due to an unexpected ___ in the third-party data integration. I will send a full ___ by tomorrow EOD.`,["proactively","dependency","update"],"Delay notice: proactively, dependency, update."))
      else if(pn===8) drills.push(write(id,`Write a professional client incident email:\nThe payment processing service was down from 09:15 to 10:47 UTC today. Approximately 300 transactions were affected. The issue was caused by an expired API key for the payment gateway. All failed transactions have been reprocessed.`,120))
      else if(pn===9) drills.push(write(id,`Write a scope change explanation to a client:\nThe client asked to add real-time notifications during the final week of the project. This was not in the original scope and would add 2 weeks of development. Offer two options: (1) add to this phase with revised timeline and cost, or (2) defer to next phase.`,120))
      else drills.push(speak(id,"Speak for 90 seconds: you are on a client call after a sprint review demo. The client raised three pieces of feedback. Respond professionally: thank them, confirm each piece of feedback by repeating it back, and commit to discussing with your team and sending a response by a specific date."))
    }
    return{id:pid,phaseNumber:pn,title:TITLES[pn-1],objective:OBJS[pn-1],drills}
  })
)

/* ── Week 4 · Day 5 ── Full Simulation Week ─────────────────────────────── */

const W4D5=mk(4,5,
  "Week 4 Review — Full Workplace Simulation",
  "Integrate all Week 4 skills in realistic, end-to-end workplace communication scenarios.",
  "**Panduan cepat — ringkasan Week 4 — siklus komunikasi lengkap**:\n1. Daily standup → singkat dan spesifik (30 detik, 3 bagian: kemarin/hari ini/hambatan)\n2. Proposal teknis → terstruktur dan berbasis bukti (masalah → solusi → cara kerja → trade-off → rekomendasi)\n3. Code review → konstruktif dan spesifik (akui yang baik → masalah spesifik → saran konkret)\n4. Update klien → empatik dan bahasa sederhana (dampak dulu, bukan teknisnya)\n5. Eskalasi → dampak dulu, kemudian sebab, kemudian apa yang dibutuhkan\n\n**Toolkit register (gaya bahasa)**:\n- Standup: ringkas, faktual, present tense\n- Proposal: terstruktur, berbasis bukti, sebutkan trade-off\n- Code review: spesifik, konstruktif, tentang kode bukan orangnya\n- Klien: empatik, bahasa sederhana, proaktif sebelum diminta\n- Eskalasi: dampak ke bisnis dulu, kemudian sebab teknis, kemudian apa yang dibutuhkan",
  gp("w4d5",(pid,pn)=>{
    const TITLES=["Standup Review MCQ","Proposal Language Review","Code Review Tone Review","Client Communication Review","Mixed Scenario MCQ","Write: Standup + Blocker","Write: Proposal Summary","Write: Client Incident Update","Write: Code Review Comment Set","Speak: End-to-End Scenario"]
    const OBJS=Array.from({length:10},(_,i)=>`Apply all Week 4 communication skills in integrated IT workplace scenarios — phase ${i+1}.`)
    const drills:Drill[]=[]
    for(let i=0;i<25;i++){
      const id=`${pid}_${String(i+1).padStart(2,"0")}`
      if(pn<=2) drills.push(mcq(id,`Which response to a client asking about a delayed feature is most professional? #${i+1}`,["a:It's almost ready.","b:I want to proactively update you: the feature will be ready by [date+3]. The delay is due to a third-party dependency. I will confirm once deployed.","c:It's not our fault.","d:Soon."],"b","Komunikasi penundaan yang baik ke klien harus mencakup empat hal: PROAKTIF (kita yang memberi tahu, bukan mereka yang tanya), TANGGAL BARU yang spesifik (bukan 'soon' atau 'almost ready'), ALASAN SINGKAT yang mudah dipahami, dan JANJI KONFIRMASI setelah selesai. Pilihan B mencakup semua itu."))
      else if(pn<=4) drills.push(fill(id,`I ___ recommend migrating to the event-driven architecture. The primary ___ is a 50% reduction in service coupling. The main trade-off is ___ operational complexity during transition, which we can ___ by rolling it out service by service.`,["strongly","advantage","increased","mitigate"],"Proposal language: strongly recommend, advantage, trade-off, mitigate."))
      else if(pn<=6) drills.push(fix(id,`Yesterday: done stuff. Today: same. No blockers I think.`,`Yesterday: Completed the Stripe webhook integration (ENG-312) and merged to staging.\nToday: Begin QA support for ENG-315 and target completion by 16:00.\nBlockers: None currently.`,"Standup: specific tasks, tickets, and clear blocker status."))
      else if(pn<=8) drills.push(write(id,`Write a complete client incident email for this scenario:\nThe mobile app was returning blank screens for all users from 18:00 to 19:15 UTC. Root cause: a misconfigured CDN cache invalidation pushed an empty JavaScript bundle. Service restored after rollback at 19:15. 2,800 users affected.`,130))
      else if(pn===9) drills.push(write(id,`Write 3 code review comments (one blocking, one non-blocking, one question) for a PR that: (1) has a SQL injection risk using string concatenation, (2) uses 'var' instead of 'const', (3) has an unusual sorting algorithm you want to understand.`,100))
      else drills.push(speak(id,"Full simulation — speak for 3 minutes continuously:\nPart 1 (30s): Give your standup update.\nPart 2 (60s): Propose switching from REST to GraphQL for your internal APIs.\nPart 3 (30s): Respond to a colleague who disagrees with the proposal.\nPart 4 (60s): Update a client about a 2-day feature delay."))
    }
    return{id:pid,phaseNumber:pn,title:TITLES[pn-1],objective:OBJS[pn-1],drills}
  })
)

export const WEEK4_DAYS: DayPlan[] = [W4D1, W4D2, W4D3, W4D4, W4D5]
